/// The longest common prefix of all words ("" for an empty list).
pub fn common_prefix(words: List[Str]) -> Str {
  var prefix = words.first().unwrap_or("")
  for w in words {
    while not w.starts_with(prefix) and not prefix.is_empty() {
      prefix = prefix.slice(0, prefix.len() - 1)
    }
  }
  return prefix
}
